    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The three adjacent nonzero cells in the top row are the color key.
    key_start = next(c for c in range(w - 2)
                     if all(grid[0][c + k] != 0 for k in range(3)))
    for k in range(3):
        col = key_start + k
        color = grid[0][col]
        if k == 1:
            # The middle color continues down the full height.
            for r in range(1, h):
                out[r][col] = color
            continue
